static inline kernel_cap_t cap_drop_nfsd_set(const kernel_cap_t a) /* <=== cap_drop_nfsd_set */ 
{
	const kernel_cap_t __cap_fs_set = CAP_NFSD_SET;
	return cap_drop(a, __cap_fs_set);
}

const struct cred *override_creds(const struct cred *new) /* <=== override_creds */ 
{
	const struct cred *old = current->cred;

	kdebug("override_creds(%p{%d,%d})", new,
	       atomic_read(&new->usage),
	       read_cred_subscribers(new));

	validate_creds(old);
	validate_creds(new);
	get_cred(new);
	alter_cred_subscribers(new, 1);
	rcu_assign_pointer(current->cred, new);
	alter_cred_subscribers(old, -1);

	kdebug("override_creds() = %p{%d,%d}", old,
	       atomic_read(&old->usage),
	       read_cred_subscribers(old));
	return old;
}

static inline void alter_cred_subscribers(const struct cred *_cred, int n) /* <=== alter_cred_subscribers */ 
{
#ifdef CONFIG_DEBUG_CREDENTIALS
	struct cred *cred = (struct cred *) _cred;

	atomic_add(n, &cred->subscribers);
#endif
}

static inline void validate_creds(const struct cred *cred) /* <=== validate_creds */ 
{
}

static inline void put_cred(const struct cred *_cred) /* <=== put_cred */ 
{
	struct cred *cred = (struct cred *) _cred;

	validate_creds(cred);
	if (atomic_dec_and_test(&(cred)->usage))
		__put_cred(cred);
}

void set_groups(struct cred *new, struct group_info *group_info) /* <=== set_groups */ 
{
	put_group_info(new->group_info);
	get_group_info(group_info);
	new->group_info = group_info;
}

static inline struct group_info *get_group_info(struct group_info *gi) /* <=== get_group_info */ 
{
	atomic_inc(&gi->usage);
	return gi;
}

static inline kernel_cap_t cap_raise_nfsd_set(const kernel_cap_t a, /* <=== cap_raise_nfsd_set */ 
					      const kernel_cap_t permitted)
{
	const kernel_cap_t __cap_nfsd_set = CAP_NFSD_SET;
	return cap_combine(a,
			   cap_intersect(permitted, __cap_nfsd_set));
}

static inline kernel_cap_t cap_drop(const kernel_cap_t a, /* <=== cap_drop */ 
				    const kernel_cap_t drop)
{
	kernel_cap_t dest;
	CAP_BOP_ALL(dest, a, drop, &~);
	return dest;
}

void __put_cred(struct cred *cred) /* <=== __put_cred */ 
{
	kdebug("__put_cred(%p{%d,%d})", cred,
	       atomic_read(&cred->usage),
	       read_cred_subscribers(cred));

	BUG_ON(atomic_read(&cred->usage) != 0);
#ifdef CONFIG_DEBUG_CREDENTIALS
	BUG_ON(read_cred_subscribers(cred) != 0);
	cred->magic = CRED_MAGIC_DEAD;
	cred->put_addr = __builtin_return_address(0);
#endif
	BUG_ON(cred == current->cred);
	BUG_ON(cred == current->real_cred);

	call_rcu(&cred->rcu, put_cred_rcu);
}

static inline struct cred *get_new_cred(struct cred *cred) /* <=== get_new_cred */ 
{
	atomic_inc(&cred->usage);
	return cred;
}

static inline kernel_cap_t cap_combine(const kernel_cap_t a, /* <=== cap_combine */ 
				       const kernel_cap_t b)
{
	kernel_cap_t dest;
	CAP_BOP_ALL(dest, a, b, |);
	return dest;
}

int nfsexp_flags(struct svc_rqst *rqstp, struct svc_export *exp) /* <=== nfsexp_flags */ 
{
	struct exp_flavor_info *f;
	struct exp_flavor_info *end = exp->ex_flavors + exp->ex_nflavors;

	for (f = exp->ex_flavors; f < end; f++) {
		if (f->pseudoflavor == rqstp->rq_cred.cr_flavor)
			return f->flags;
	}
	return exp->ex_flags;

}

struct cred *prepare_creds(void) /* <=== prepare_creds */ 
{
	struct task_struct *task = current;
	const struct cred *old;
	struct cred *new;

	validate_process_creds();

	new = kmem_cache_alloc(cred_jar, GFP_KERNEL);
	if (!new)
		return NULL;

	kdebug("prepare_creds() alloc %p", new);

	old = task->cred;
	memcpy(new, old, sizeof(struct cred));

	atomic_set(&new->usage, 1);
	set_cred_subscribers(new, 0);
	get_group_info(new->group_info);
	get_uid(new->user);
	get_user_ns(new->user_ns);

#ifdef CONFIG_KEYS
	key_get(new->session_keyring);
	key_get(new->process_keyring);
	key_get(new->thread_keyring);
	key_get(new->request_key_auth);
#endif

#ifdef CONFIG_SECURITY
	new->security = NULL;
#endif

	if (security_prepare_creds(new, old, GFP_KERNEL) < 0)
		goto error;
	validate_creds(new);
	return new;

error:
	abort_creds(new);
	return NULL;
}

void groups_sort(struct group_info *group_info) /* <=== groups_sort */ 
{
	sort(group_info->gid, group_info->ngroups, sizeof(*group_info->gid),
	     gid_cmp, NULL);
}

static inline int read_cred_subscribers(const struct cred *cred) /* <=== read_cred_subscribers */ 
{
#ifdef CONFIG_DEBUG_CREDENTIALS
	return atomic_read(&cred->subscribers);
#else
	return 0;
#endif
}

static inline const struct cred *get_cred(const struct cred *cred) /* <=== get_cred */ 
{
	struct cred *nonconst_cred = (struct cred *) cred;
	validate_creds(cred);
	return get_new_cred(nonconst_cred);
}

void abort_creds(struct cred *new) /* <=== abort_creds */ 
{
	kdebug("abort_creds(%p{%d,%d})", new,
	       atomic_read(&new->usage),
	       read_cred_subscribers(new));

#ifdef CONFIG_DEBUG_CREDENTIALS
	BUG_ON(read_cred_subscribers(new) != 0);
#endif
	BUG_ON(atomic_read(&new->usage) < 1);
	put_cred(new);
}

static inline void set_cred_subscribers(struct cred *cred, int n) /* <=== set_cred_subscribers */ 
{
#ifdef CONFIG_DEBUG_CREDENTIALS
	atomic_set(&cred->subscribers, n);
#endif
}

struct group_info *groups_alloc(int gidsetsize) /* <=== groups_alloc */ 
{
	struct group_info *gi;
	unsigned int len;

	len = sizeof(struct group_info) + sizeof(kgid_t) * gidsetsize;
	gi = kmalloc(len, GFP_KERNEL_ACCOUNT|__GFP_NOWARN|__GFP_NORETRY);
	if (!gi)
		gi = __vmalloc(len, GFP_KERNEL_ACCOUNT, PAGE_KERNEL);
	if (!gi)
		return NULL;

	atomic_set(&gi->usage, 1);
	gi->ngroups = gidsetsize;
	return gi;
}

static inline kernel_cap_t cap_intersect(const kernel_cap_t a, /* <=== cap_intersect */ 
					 const kernel_cap_t b)
{
	kernel_cap_t dest;
	CAP_BOP_ALL(dest, a, b, &);
	return dest;
}

typeDefs:
struct group_info {
	atomic_t	usage;
	int		ngroups;
	kgid_t		gid[0];
}

